sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 offset;
uniform float feather;
uniform float mask;
half4 main(float2 coord) {
    float2 box = max(size, float2(1));
    if (coord.x < 0 || coord.y < 0 || coord.x >= box.x || coord.y >= box.y) return image.eval(coord);
    half4 color = image.eval(mod(coord - offset, box));
    if (feather > 0) {
        float2 seam = mod(offset, box);
        float2 d = abs(coord - seam);
        d = min(d, box - d);
        float2 w = smoothstep(float2(0), max(feather * box * 0.5, float2(0.001)), d);
        if (min(seam.x, box.x - seam.x) < 0.5) w.x = 1;
        if (min(seam.y, box.y - seam.y) < 0.5) w.y = 1;
        color = mix(image.eval(coord), color, half(w.x * w.y));
    }
    if (mask > 0.5) color *= image.eval(coord).a;
    return color;
}
